<script>(function(){
function syncDestination(root){var s=root.querySelector('[data-waste-destination]'),f=root.querySelector('[data-waste-utilizer-field]');if(!s||!f)return;f.style.display=s.value==='utilizer'?'block':'none';var u=f.querySelector('select[name="utilizer_id"]');if(u)u.required=s.value==='utilizer';}
function syncPlan(root){var m=root.querySelector('[data-waste-plan-mode]');if(!m)return;var e=root.querySelector('[data-waste-plan-exact]'),f=root.querySelector('[data-waste-plan-from]'),t=root.querySelector('[data-waste-plan-to]');var exact=m.value==='exact',range=m.value==='range';if(e){e.style.display=exact?'block':'none';e.required=exact;}if(f){f.style.display=range?'block':'none';f.required=range;}if(t){t.style.display=range?'block':'none';t.required=range;}}
async function preview(form){var r=form.querySelector('[data-waste-preview-result]'),b=form.querySelector('[data-waste-create-submit]');if(r)r.textContent='Проверка...';if(b)b.disabled=true;try{var x=await fetch('<?=app_url('/company/trips/departures/preview')?>',{method:'POST',body:new FormData(form),credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest'}}),p=await x.json();if(!x.ok||!p.success){if(r)r.textContent=p.message||('Не найдены: '+(p.missing||[]).join(', ')+'; заняты: '+Object.keys(p.occupied||{}).join(', '));return;}if(r)r.textContent='Найдено '+p.found_count+'/'+p.input_count+', '+Number(p.total_mass_kg||0).toLocaleString('ru-RU')+' кг, конфликтов нет.';if(b)b.disabled=false;}catch(e){if(r)r.textContent='Ошибка проверки.';}}
async function loadModal(kind,id){var modal='waste-trip-'+kind+'-modal',body=document.getElementById('waste-trip-'+kind+'-body');body.innerHTML='<div class="modal-body">Загрузка...</div>';openModal(modal);try{var x=await fetch('<?=app_url('/company/trips/departures')?>/'+encodeURIComponent(id)+'/modal-'+kind,{credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest'}});body.innerHTML=await x.text();if(!x.ok)return;var title=body.querySelector('[data-waste-modal-title]');if(title)document.getElementById('waste-trip-'+kind+'-title').textContent=title.dataset.wasteModalTitle;wireForm(body);}catch(e){body.innerHTML='<div class="modal-body"><div class="notice warn">Не удалось загрузить рейс.</div></div>';}}
document.querySelectorAll('.waste-row[data-waste-view]').forEach(function(row){var open=function(){loadModal('view',row.dataset.wasteView)};row.addEventListener('click',open);row.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();open();}});});
document.addEventListener('click',function(e){var b=e.target.closest('[data-waste-open-edit]');if(!b)return;closeModal('waste-trip-view-modal');loadModal('edit',b.dataset.wasteOpenEdit);});
function wireForm(f){if(f.matches('[data-linear-trip-form]')&&typeof window.initLinearTripForm==='function')window.initLinearTripForm(f);syncDestination(f);syncPlan(f);var d=f.querySelector('[data-waste-destination]');if(d&&!d.dataset.wasteBound){d.dataset.wasteBound='1';d.addEventListener('change',function(){syncDestination(f)});}var p=f.querySelector('[data-waste-plan-mode]');if(p&&!p.dataset.wasteBound){p.dataset.wasteBound='1';p.addEventListener('change',function(){syncPlan(f)});}var v=f.querySelector('[data-waste-preview]');if(v&&!v.dataset.wasteBound){v.dataset.wasteBound='1';v.addEventListener('click',function(){preview(f)});}var ids=f.querySelector('[data-waste-request-ids]');if(ids&&!ids.dataset.wasteBound){ids.dataset.wasteBound='1';ids.addEventListener('input',function(){var b=f.querySelector('[data-waste-create-submit]');if(b)b.disabled=true;});}}
document.querySelectorAll('form').forEach(wireForm);
document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('[data-linear-trip-form]').forEach(wireForm);});
<?php if($showCreateModal):?>openModal('waste-trip-create-modal');<?php endif;?>
<?php if($openTripId>0):?>loadModal('view',<?=$openTripId?>);<?php endif;?>
<?php if($openEditId>0):?>loadModal('edit',<?=$openEditId?>);<?php endif;?>
})();</script>
